#include <stdio.h>

typedef enum { THINKING, HUNGRY, EATING } State;

typedef struct { int id; State state; } Philosopher;

int forks[5] = {1, 1, 1, 1, 1};

void pickup(Philosopher *p) {
    int left = p->id;
    int right = (p->id + 1) % 5;
    if (p->state == HUNGRY && forks[left] && forks[right]) {
        forks[left] = 0; forks[right] = 0;
        p->state = EATING;
        printf("P%d picks up forks and eats\n", p->id);
    }
}

void putdown(Philosopher *p) {
    int left = p->id;
    int right = (p->id + 1) % 5;
    forks[left] = 1; forks[right] = 1;
    p->state = THINKING;
    printf("P%d puts down forks and thinks\n", p->id);
}

int main() {
    Philosopher ps[5];
    for (int i = 0; i < 5; i++) { ps[i].id = i; ps[i].state = THINKING; }
    for (int round = 0; round < 3; round++) {
        for (int i = 0; i < 5; i++) {
            ps[i].state = HUNGRY;
            printf("P%d is hungry\n", i);
            pickup(&ps[i]);
        }
        for (int i = 0; i < 5; i++) if (ps[i].state == EATING) putdown(&ps[i]);
    }
    return 0;
}
